/* ---- motion ------------------------------------------------------------------ */
@media (prefers-reduced-motion:no-preference){
  .ch-hero__text>*{animation:ch-rise .9s var(--ch-ease) both}
  .ch-hero__text>*:nth-child(2){animation-delay:.08s}
  .ch-hero__text>*:nth-child(3){animation-delay:.16s}
  .ch-hero__text>*:nth-child(4){animation-delay:.24s}
  .ch-hero__text>*:nth-child(5){animation-delay:.32s}
  .ch-hero__media{animation:ch-rise 1.1s .1s var(--ch-ease) both}
  .ch-chip__dot{animation:ch-pulse 2.4s ease-in-out infinite}
}
@keyframes ch-rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
@keyframes ch-pulse{50%{box-shadow:0 0 0 7px rgba(62,154,91,.08)}}

/* ---- responsive ------------------------------------------------------------ */
@media (max-width:1100px){
  .ch-menus--three{grid-template-columns:1fr;max-width:38rem;margin-inline:auto}
  .ch-addgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ch-promgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ch-foot__grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ch-foot__grid>.ch-foot__col:first-child{grid-column:1/-1}
  .ch-mosaic{grid-template-columns:repeat(6,minmax(0,1fr))}
  .ch-tile.is-a{grid-column:span 3}
  .ch-tile.is-b,.ch-tile.is-c{grid-column:span 3}
  .ch-tile.is-d,.ch-tile.is-e{grid-column:span 3}
}
@media (max-width:960px){
  body header .ch-header{height:4.5rem;grid-template-columns:1fr auto auto;gap:.9rem}
  .ch-header .ch-nav{order:3}
  .ch-hero__grid,.ch-intro__grid,.ch-evening__grid,.ch-quote__grid,.ch-where__grid,.ch-phero__grid,.ch-diet__grid,.ch-faq__grid,.ch-svc,.ch-about-hero__grid,.ch-story__grid,.ch-sourcing__grid,.ch-book__grid,.ch-foot__top,.ch-head--split{grid-template-columns:1fr}
  .ch-hero__media{justify-self:start;width:min(100%,26rem);margin-left:1.5rem}
  .ch-evening__side,.ch-faq__left,.ch-book__text{position:static}
  .ch-svc.is-flip>.ch-svc__img{order:0}
  body .ch-svc__img,body .ch-svc.is-flip .ch-svc__img{aspect-ratio:4/3;max-height:none}
  body .ch-phero__img,.ch-phero__stack,body .ch-about-hero__img{justify-self:start}
  body .ch-quote__img{max-width:22rem}
  body .ch-sourcing__img{max-width:24rem}
  .ch-intro__grid>.ch-eyebrow{padding-top:0}
  .ch-menus--two{grid-template-columns:1fr;max-width:34rem}
  .ch-menus--two .ch-menu:nth-child(2){margin-top:0}
}
@media (max-width:700px){
  .ch-facts{grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
  .ch-facts dd{font-size:.8rem}
  .ch-chip{left:-1rem;bottom:2rem;right:auto}
  .ch-chip em{display:none}
  .ch-mosaic{grid-template-columns:1fr 1fr;grid-auto-rows:14rem;gap:.6rem}
  .ch-tile.is-a{grid-column:1/-1;grid-row:span 2}
  .ch-tile.is-b,.ch-tile.is-c,.ch-tile.is-d,.ch-tile.is-e{grid-column:span 1}
  .ch-tile__body{padding:1rem}
  .ch-tile b{font-size:1.15rem}
  .ch-tile em{font-size:.78rem}
  .ch-time::before{left:4.15rem}
  .ch-time li{grid-template-columns:3.4rem minmax(0,1fr);gap:1.5rem}
  .ch-time li::before{left:3.93rem}
  .ch-time__t{font-size:1.15rem}
  .ch-quote__more{grid-template-columns:1fr}
  .ch-areas{grid-template-columns:1fr}
  .ch-areas li{min-height:0}
  .ch-diet__list li{grid-template-columns:1fr;gap:.35rem}
  .ch-addgrid,.ch-promgrid{grid-template-columns:1fr}
  .ch-form__row,.ch-form__row--3{grid-template-columns:1fr}
  .ch-cal__m{grid-template-columns:1fr auto;gap:.6rem 1rem}
  .ch-cal__bar{grid-column:1/-1;grid-row:2}
  .ch-supply div{grid-template-columns:1fr;gap:.3rem}
  .ch-past .sfcore-portfolio__grid{grid-template-columns:1fr!important}
  .ch-foot__grid{grid-template-columns:1fr}
  .ch-foot__bar{flex-direction:column}
  .ch-header .ch-header__cta{display:none}
  body header .ch-header{grid-template-columns:1fr auto}
  .ch-menu footer{flex-direction:column;align-items:center;gap:.4rem}
  body .ch-faq details p{padding-right:0}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{transition-duration:.01ms!important;animation-duration:.01ms!important}
}

/* ---- refinements ------------------------------------------------------------ */
.ch-faq__grid{border-top:0;padding-top:clamp(3rem,6vw,5rem)}
.ch-dark+.ch-faqsec .ch-faq__grid{padding-top:0}
.ch-tile::after{background:linear-gradient(180deg,rgba(23,17,15,0) 30%,rgba(23,17,15,.5) 60%,rgba(23,17,15,.92) 100%)}
@media (max-width:700px){
  .ch-hero__media{margin:0;width:calc(100% - .75rem)}
  .ch-hero__media::before{transform:translate(.75rem,-.75rem)}
  .ch-form__row--3{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ch-form__row--3>label:last-child{grid-column:1/-1}
}
